package org.local.donusturucu;
import java.io.*;import java.util.*;import java.util.regex.*;
/** Translation happens elsewhere; original SRT supplies every time code. */
public final class SubtitleFiles {
 static String read(File file)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();InputStream in=new FileInputStream(file);try{byte[]buf=new byte[8192];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);}finally{in.close();}return new String(b.toByteArray(),"UTF-8").replace("\uFEFF","").replace("\r\n","\n").replace('\r','\n').trim();}
 static long time(String value)throws Exception{if(!value.matches("[0-9]{2,}:[0-5][0-9]:[0-5][0-9],[0-9]{3}"))throw new IOException("subtitle_invalid");String[]v=value.split("[:,]");return ((Long.parseLong(v[0])*60+Long.parseLong(v[1]))*60+Long.parseLong(v[2]))*1000+Long.parseLong(v[3]);}
 static List<String[]> parse(File file)throws Exception{List<String[]>cues=new ArrayList<String[]>();for(String block:read(file).split("\n[ \\t]*\n")){String[]lines=block.split("\n");if(lines.length<3||!lines[0].matches("[0-9]+"))throw new IOException("subtitle_invalid");String[]pair=lines[1].trim().split(" --> ");if(pair.length!=2||time(pair[1])<=time(pair[0]))throw new IOException("subtitle_invalid");StringBuilder text=new StringBuilder();for(int i=2;i<lines.length;i++){if(text.length()>0)text.append(' ');text.append(lines[i].trim());}if(text.toString().trim().isEmpty())throw new IOException("subtitle_invalid");cues.add(new String[]{lines[0],lines[1].trim(),text.toString()});}return cues;}
 public static String exportText(File original)throws Exception{StringBuilder out=new StringBuilder();for(String[]cue:parse(original))out.append(cue[2]).append('\n');return out.toString();}
 public static String restore(File translated,File original)throws Exception{List<String[]>cues=parse(original);String[]lines=read(translated).split("\n",-1);if(lines.length!=cues.size())throw new IOException("subtitle_line_count");StringBuilder out=new StringBuilder();for(int i=0;i<lines.length;i++){if(lines[i].trim().isEmpty())throw new IOException("subtitle_line_count");String[]cue=cues.get(i);out.append(cue[0]).append('\n').append(cue[1]).append('\n').append(lines[i].trim()).append("\n\n");}return out.toString();}
 public static File write(String content,String ext,File work)throws Exception{File result=new File(work,"subtitle."+ext);Writer writer=new OutputStreamWriter(new FileOutputStream(result),"UTF-8");try{writer.write(content);}finally{writer.close();}return result;}
}
